        getHint(state, results) {
            var ds = state.domainState;
            var period = state.currentPeriod;
            if (period === 1 && ds.payerBetaExcluded) {
                return window.mySimulation.t('hint_payer_beta');
            }
            if (period >= 2 && ds.formularyCoverage < 50) {
                return window.mySimulation.t('hint_low_formulary');
            }
            if (period >= 3 && ds.prescriberReach < 500) {
                return window.mySimulation.t('hint_low_reach');
            }
            if (period >= 3 && ds.persistenceRate < 50) {
                return window.mySimulation.t('hint_low_persistence');
            }
            if (period >= 4 && ds.lifecycleScore < 20) {
                return window.mySimulation.t('hint_lifecycle_warning');
            }
            if (results.marketShare > 15) {
                return window.mySimulation.t('hint_strong_share');
            }
            return null;
        }

