            var ds = window.mySimulation.state.domainState;
            var totalRev = ds.cumulativeRevenue;
            var finalShare = ds.marketShare;
            var lei = ds.leiScore;
            var performance = 'Needs Improvement';
            if (lei >= 70) performance = 'Excellent Launch Execution';
            else if (lei >= 50) performance = 'Good Launch Performance';
            else if (lei >= 30) performance = 'Developing Launch Strategy';
            var insights = [];
            if (ds.formularyCoverage >= 70) insights.push('Strong formulary access — payer strategy was well executed.');
            else insights.push('Formulary coverage was below target. Early market access investment is critical.');
            if (ds.persistenceRate >= 60) insights.push('Good patient persistence — support programs drove adherence.');
            else insights.push('Low patient persistence. Investing in patient support earlier would have improved lifetime value.');
            if (ds.lifecycleScore >= 50) insights.push('Proactive lifecycle management helped defend against generic erosion.');
            else insights.push('Weak generic defense. Lifecycle planning should start during launch, not after.');
            if (ds.payerBetaExcluded) insights.push('Payer Beta was permanently excluded due to insufficient early market access investment — a costly strategic error.');
            return {
                totalRevenue: totalRev,
                finalMarketShare: finalShare,
                leiScore: lei,
                performance: performance,
                insights: insights
            };
        }

